import React, { useState, useEffect } from 'react';

/**
 * Modernized React UI Component: Coact2aScreen
 * Source Mainframe Screen: Mapset COACT2A, Map COACT2A
 * Auto-generated by Antigravity Modernization Platform (MMAP-AGENT-06).
 * Theme: IBM 3270 Phosphor / Slate Dark Mode
 */
export default function Coact2aScreen({ onSubmitSuccess, onCancel }) {
  const [formData, setFormData] = useState({
    coactup_id: '',
    option: '',
    input_data: '',
    status_msg: ''
  });
  const [statusMsg, setStatusMsg] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [darkMode, setDarkMode] = useState(true);

  // Keyboard navigation listener (3270 Terminal Emulation)
  useEffect(() => {
    const handleKeyDown = (e) => {
      if (e.key === 'Enter') {
        e.preventDefault();
        handleSubmit('ENTER');
      } else if (e.key === 'F3') {
        e.preventDefault();
        if (onCancel) onCancel();
      } else if (e.key === 'F4') {
        e.preventDefault();
        handleClear();
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [formData]);

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData((prev) => ({ ...prev, [name]: value }));
  };

  const handleSubmit = async (actionKey = 'ENTER') => {
    setIsSubmitting(true);
    setStatusMsg('Processing transaction...');
    try {
      const res = await fetch('/api/v1/screens/coact2a/submit', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ action: actionKey, payload: formData }),
      });
      const data = await res.json();
      setStatusMsg(data.message || 'Transaction executed successfully.');
      if (onSubmitSuccess) onSubmitSuccess(data);
    } catch (err) {
      setStatusMsg('Error executing transaction: ' + err.message);
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleClear = () => {
    setFormData({
    coactup_id: '',
    option: '',
    input_data: '',
    status_msg: ''
    });
    setStatusMsg('Screen cleared.');
  };

  return (
    <div className={`w-full max-w-4xl mx-auto border rounded-xl shadow-2xl p-6 transition-colors duration-200 ${
      darkMode ? 'bg-slate-950 border-slate-800 text-slate-200' : 'bg-white border-gray-200 text-gray-800'
    }`}>
      {/* Screen Header */}
      <div className="flex items-center justify-between border-b border-slate-800 pb-4 mb-6">
        <div>
          <div className="flex items-center gap-2">
            <span className="px-2 py-0.5 text-[11px] font-mono bg-blue-900/60 text-blue-300 border border-blue-700/50 rounded">
              3270 MODERNIZED
            </span>
            <span
              data-bms-mapset="COACT2A"
              data-bms-map="COACT2A"
              className="text-xs font-mono text-slate-400"
            >
              MAPSET: COACT2A | MAP: COACT2A
            </span>
          </div>
          <h2 className="text-xl font-bold mt-1">Account Profile Modification</h2>
        </div>
        <div className="flex items-center gap-3">
          <button
            type="button"
            onClick={() => setDarkMode(!darkMode)}
            className="text-xs font-mono px-2.5 py-1 rounded bg-slate-800 hover:bg-slate-700 text-slate-300 border border-slate-700"
          >
            {darkMode ? 'Phosphor Mode' : 'Light Mode'}
          </button>
          <div className="text-xs font-mono text-emerald-400 bg-emerald-950/60 border border-emerald-800 px-2.5 py-1 rounded">
            Online • Connected
          </div>
        </div>
      </div>

      {/* Status Line */}
      {statusMsg && (
        <div className="mb-4 px-3 py-2 bg-slate-900 border border-slate-700 rounded text-xs font-mono text-amber-300 flex items-center justify-between">
          <span>HOST: {statusMsg}</span>
        </div>
      )}

      {/* Screen Form Fields */}
      <form onSubmit={(e) => { e.preventDefault(); handleSubmit('ENTER'); }} className="space-y-4">
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
          <div className="flex flex-col gap-1">
            <label htmlFor="coactup_id" className="text-xs font-semibold text-gray-400 uppercase tracking-wider">
              Record Identifier <span className="text-blue-400 font-mono text-[10px]">[Numeric]</span>
            </label>
            <input
              id="coactup_id"
              name="coactup_id"
              data-bms-field="COACTUP_ID"
              data-bms-map="COACT2A"
              data-testid="bms-coactup_id"
              aria-label="Record Identifier"
              type="number"
              
              inputMode="numeric" pattern="[0-9]*"
              
              maxLength={12}
              value={formData.coactup_id}
              onChange={handleChange}
              placeholder="Record Identifier (Max 12)"
              className="px-3 py-2 bg-slate-900 border border-slate-700 rounded-md text-slate-100 placeholder-slate-500 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent font-mono"
            />
          </div>
          <div className="flex flex-col gap-1">
            <label htmlFor="option" className="text-xs font-semibold text-gray-400 uppercase tracking-wider">
              Transaction Option / Command 
            </label>
            <input
              id="option"
              name="option"
              data-bms-field="OPTION"
              data-bms-map="COACT2A"
              data-testid="bms-option"
              aria-label="Transaction Option / Command"
              type="text"
              
              
              
              maxLength={4}
              value={formData.option}
              onChange={handleChange}
              placeholder="Transaction Option / Command (Max 4)"
              className="px-3 py-2 bg-slate-900 border border-slate-700 rounded-md text-slate-100 placeholder-slate-500 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent font-mono"
            />
          </div>
          <div className="flex flex-col gap-1">
            <label htmlFor="input_data" className="text-xs font-semibold text-gray-400 uppercase tracking-wider">
              Input Parameters / Payload 
            </label>
            <input
              id="input_data"
              name="input_data"
              data-bms-field="INPUT_DATA"
              data-bms-map="COACT2A"
              data-testid="bms-input_data"
              aria-label="Input Parameters / Payload"
              type="text"
              
              
              
              maxLength={40}
              value={formData.input_data}
              onChange={handleChange}
              placeholder="Input Parameters / Payload (Max 40)"
              className="px-3 py-2 bg-slate-900 border border-slate-700 rounded-md text-slate-100 placeholder-slate-500 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent font-mono"
            />
          </div>
          <div className="flex flex-col gap-1">
            <label htmlFor="status_msg" className="text-xs font-semibold text-gray-400 uppercase tracking-wider">
              Status Message 
            </label>
            <input
              id="status_msg"
              name="status_msg"
              data-bms-field="STATUS_MSG"
              data-bms-map="COACT2A"
              data-testid="bms-status_msg"
              aria-label="Status Message"
              type="text"
              readOnly aria-readonly="true"
              
              
              maxLength={30}
              value={formData.status_msg}
              onChange={handleChange}
              placeholder="Status Message (Max 30)"
              className="px-3 py-2 bg-slate-900 border border-slate-700 rounded-md text-slate-100 placeholder-slate-500 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent font-mono"
            />
          </div>
        </div>

        {/* Action Button Bar */}
        <div className="flex items-center justify-between pt-6 border-t border-slate-800 mt-6">
          <div className="flex items-center gap-2">
            <button
              type="button"
              name="CLEAR"
              aria-label="Clear Form (F4)"
              data-action="CLEAR"
              onClick={handleClear}
              className="px-4 py-2 bg-slate-800 hover:bg-slate-700 text-slate-300 rounded text-xs font-medium transition"
            >
              Clear Form (F4)
            </button>
            <button
              type="button"
              name="EXIT"
              aria-label="Exit (PF3)"
              data-action="PF3"
              onClick={() => { if (onCancel) onCancel(); }}
              className="px-4 py-2 bg-slate-800 hover:bg-slate-700 text-slate-300 rounded text-xs font-medium transition"
            >
              Exit (PF3)
            </button>
          </div>
          <button
            type="submit"
            name="SUBMIT"
            aria-label="Submit (ENTER)"
            data-action="ENTER"
            disabled={isSubmitting}
            className="px-6 py-2 bg-blue-600 hover:bg-blue-500 disabled:opacity-50 text-white rounded text-xs font-semibold shadow-lg shadow-blue-600/30 transition flex items-center gap-2"
          >
            {isSubmitting ? 'Transmitting...' : 'Submit (ENTER)'}
          </button>
        </div>
      </form>
    </div>
  );
}
